{return (GetBlur1(uvi)+GetBlur1(float2(1-uvi.x,uvi.y)));}

float3 getb3 (float2 uvi)
{return (GetBlur3(uvi)+GetBlur3(float2(1-uvi.x,uvi.y)));}

float3 noise3 (float2 uvi)
{return (tex2D(snh,uvi) + 0.5*tex2D(snh,uvi*2+time*.01))/1.5;}

